package com.pudgy.tickmetronome;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.Range;

@ConfigGroup("hotkeytickmetronome")
public interface TickMetronomeConfig extends Config
{
	@ConfigSection(name = "Presets", description = "Tick-cycle presets and their hotkeys.", position = 0)
	String presets = "presets";

	@ConfigSection(name = "Display", description = "Appearance of the number above your head.", position = 1)
	String display = "display";

	@ConfigItem(keyName = "preset1Key", name = "Preset 1 hotkey", description = "Hotkey to switch to preset 1.", section = presets, position = 0)
	default Keybind preset1Key() { return Keybind.NOT_SET; }
	@Range(min = 0, max = 50)
	@ConfigItem(keyName = "preset1Length", name = "Preset 1 ticks", description = "Cycle length for preset 1 (0 = off).", section = presets, position = 1)
	default int preset1Length() { return 7; }

	@ConfigItem(keyName = "preset2Key", name = "Preset 2 hotkey", description = "Hotkey to switch to preset 2.", section = presets, position = 2)
	default Keybind preset2Key() { return Keybind.NOT_SET; }
	@Range(min = 0, max = 50)
	@ConfigItem(keyName = "preset2Length", name = "Preset 2 ticks", description = "Cycle length for preset 2 (0 = off).", section = presets, position = 3)
	default int preset2Length() { return 4; }

	@ConfigItem(keyName = "preset3Key", name = "Preset 3 hotkey", description = "Hotkey to switch to preset 3.", section = presets, position = 4)
	default Keybind preset3Key() { return Keybind.NOT_SET; }
	@Range(min = 0, max = 50)
	@ConfigItem(keyName = "preset3Length", name = "Preset 3 ticks", description = "Cycle length for preset 3 (0 = off).", section = presets, position = 5)
	default int preset3Length() { return 5; }

	@ConfigItem(keyName = "preset4Key", name = "Preset 4 hotkey", description = "Hotkey to switch to preset 4.", section = presets, position = 6)
	default Keybind preset4Key() { return Keybind.NOT_SET; }
	@Range(min = 0, max = 50)
	@ConfigItem(keyName = "preset4Length", name = "Preset 4 ticks", description = "Cycle length for preset 4 (0 = off).", section = presets, position = 7)
	default int preset4Length() { return 0; }

	@ConfigItem(keyName = "preset5Key", name = "Preset 5 hotkey", description = "Hotkey to switch to preset 5.", section = presets, position = 8)
	default Keybind preset5Key() { return Keybind.NOT_SET; }
	@Range(min = 0, max = 50)
	@ConfigItem(keyName = "preset5Length", name = "Preset 5 ticks", description = "Cycle length for preset 5 (0 = off).", section = presets, position = 9)
	default int preset5Length() { return 0; }

	@ConfigItem(keyName = "clearKey", name = "Off hotkey", description = "Hotkey to stop the metronome.", section = presets, position = 40)
	default Keybind clearKey() { return Keybind.NOT_SET; }
	@ConfigItem(keyName = "resetOnSwitch", name = "Reset on switch", description = "Restart the count at 1 when you switch presets.", section = presets, position = 41)
	default boolean resetOnSwitch() { return true; }

	@Range(min = 8, max = 120)
	@ConfigItem(keyName = "fontSize", name = "Number size", description = "Size of the number above your head.", section = display, position = 0)
	default int fontSize() { return 28; }

	@Alpha
	@ConfigItem(keyName = "textColor", name = "Number colour", description = "Colour of the number.", section = display, position = 1)
	default Color textColor() { return Color.YELLOW; }

	@Range(min = -200, max = 600)
	@ConfigItem(keyName = "heightOffset", name = "Height offset", description = "Raise (+) or lower (-) the number above your head.", section = display, position = 2)
	default int heightOffset() { return 0; }
}

package com.pudgy.tickmetronome;

import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

public class TickMetronomeOverlay extends Overlay
{
	private final Client client;
	private final TickMetronomePlugin plugin;
	private final TickMetronomeConfig config;

	@Inject
	TickMetronomeOverlay(Client client, TickMetronomePlugin plugin, TickMetronomeConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (plugin.getActiveCycle() <= 0 || plugin.getCount() < 1)
		{
			return null;
		}
		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return null;
		}
		String text = Integer.toString(plugin.getCount());
		int size = Math.max(8, Math.min(120, config.fontSize()));
		graphics.setFont(new Font(Font.SANS_SERIF, Font.BOLD, size));
		int zOffset = local.getLogicalHeight() + config.heightOffset();
		Point loc = local.getCanvasTextLocation(graphics, text, zOffset);
		if (loc != null)
		{
			OverlayUtil.renderTextLocation(graphics, loc, text, config.textColor());
		}
		return null;
	}
}

package com.pudgy.tickmetronome;

import com.google.inject.Provides;
import java.util.function.IntSupplier;
import java.util.function.Supplier;
import javax.inject.Inject;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.events.GameTick;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.Keybind;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.input.KeyManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.HotkeyListener;

@PluginDescriptor(
	name = "RtaTrueTick",
	description = "A tick counter above your player with hotkeys to switch cycle lengths on the fly.",
	tags = {"metronome", "tick", "pvm", "hotkey", "keybind", "timing"}
)
public class TickMetronomePlugin extends Plugin
{
	@Inject private Client client;
	@Inject private OverlayManager overlayManager;
	@Inject private KeyManager keyManager;
	@Inject private TickMetronomeConfig config;
	@Inject private TickMetronomeOverlay overlay;

	@Getter private int count;
	@Getter private int activeCycle;

	private HotkeyListener[] hotkeys;

	@Provides
	TickMetronomeConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(TickMetronomeConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		hotkeys = new HotkeyListener[]
		{
			preset(() -> config.preset1Key(), () -> config.preset1Length()),
			preset(() -> config.preset2Key(), () -> config.preset2Length()),
			preset(() -> config.preset3Key(), () -> config.preset3Length()),
			preset(() -> config.preset4Key(), () -> config.preset4Length()),
			preset(() -> config.preset5Key(), () -> config.preset5Length()),
			new HotkeyListener(() -> config.clearKey())
			{
				@Override
				public void hotkeyPressed() { setCycle(0); }
			}
		};
		for (HotkeyListener h : hotkeys)
		{
			keyManager.registerKeyListener(h);
		}
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		if (hotkeys != null)
		{
			for (HotkeyListener h : hotkeys)
			{
				keyManager.unregisterKeyListener(h);
			}
			hotkeys = null;
		}
		activeCycle = 0;
		count = 0;
	}

	private HotkeyListener preset(Supplier<Keybind> key, IntSupplier length)
	{
		return new HotkeyListener(key)
		{
			@Override
			public void hotkeyPressed() { setCycle(length.getAsInt()); }
		};
	}

	private void setCycle(int length)
	{
		if (length <= 0)
		{
			activeCycle = 0;
			count = 0;
			return;
		}
		activeCycle = length;
		if (config.resetOnSwitch())
		{
			count = 0;
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (activeCycle <= 0)
		{
			return;
		}
		count = (count % activeCycle) + 1;
	}
}

